    private static final int twoPow = 23;
    private static final int ROOT = 15311432;

    private static int reverseBits(int n, int k) {
        int res = 0;
        for (int i = 0; i < k; i++) {
            res = (res << 1) | (n & 1);
            n >>= 1;
        }
        return res;
    }

    private static long powerMod(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    private static long inverseMod(long a) {
        return powerMod(a, MOD - 2);
    }

    private static long[] rootsOfUnity(int k, boolean inverse) {
        long root = powerMod(ROOT, powerMod(2, twoPow - k));
        if (inverse) {
            root = inverseMod(root);
        }
        long[] roots = new long[k];
        if (k > 0) {
            roots[k - 1] = root;
        }
        for (int i = k - 1; i > 0; i--) {
            roots[i - 1] = (roots[i] * roots[i]) % MOD;
        }
        return roots;
    }

    private static long[] bitReversalPermutation(long[] array, int k) {
        long[] result = new long[array.length];
        for (int i = 0; i < array.length; i++) {
            result[reverseBits(i, k)] = array[i];
        }
