#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;
const int twoPow = 23;
const int ROOT = 15311432;

int reverseBits(int n, int k) {
    int res = 0;
    for (int i = 0; i < k; i++) {
        res = (res << 1) | (n & 1);
        n >>= 1;
    }
    return res;
}

long long powerMod(long long base, long long exp) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % MOD;
        }
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

long long inverseMod(long long a) {
    return powerMod(a, MOD - 2);
}

vector<long long> rootsOfUnity(int k, bool inverse) {
    long long root = powerMod(ROOT, powerMod(2, twoPow - k));
    if (inverse) {
        root = inverseMod(root);
    }
    vector<long long> roots(k);
    if (k > 0) {
        roots[k - 1] = root;
    }
    for (int i = k - 1; i > 0; i--) {
        roots[i - 1] = (roots[i] * roots[i]) % MOD;
    }
    return roots;
}

vector<long long> bitReversalPermutation(const vector<long long>& array, int k) {
    int n = array.size();
    vector<long long> result(n);
    for (int i = 0; i < n; i++) {
        result[reverseBits(i, k)] = array[i];
    }
    return result;
}

vector<long long> performNTT(vector<long long> coef, int k, bool inverse) {
    coef = bitReversalPermutation(coef, k);
    vector<long long> roots = rootsOfUnity(k, inverse);
    for (int s = 0; s < k; s++) {
        int segmentSize = 1 << s;
        for (int start = 0; start < (int)coef.size(); start += 2 * segmentSize) {
            long long currentRoot = 1;
            for (int j = start; j < start + segmentSize; j++) {
                long long t = (currentRoot * coef[j + segmentSize]) % MOD;
                long long u = coef[j];
                coef[j] = (u + t) % MOD;
                coef[j + segmentSize] = (u - t + MOD) % MOD;
                currentRoot = (roots[s] * currentRoot) % MOD;
            }
        }
    }
    return coef;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n_input, m;
    cin >> n_input >> m;
    int n = n_input / 2;
    vector<int> nums(m);
    int maxVal = 0;
    for (int i = 0; i < m; i++) {
        cin >> nums[i];
        maxVal = max(maxVal, nums[i]);
    }
    int minSize = n * maxVal + 1;
    int size = 1;
    int k = 0;
    while (size < minSize) {
        size <<= 1;
        k++;
    }
    vector<long long> array(size, 0);
    for (int i = 0; i < m; i++) {
        array[nums[i]] = 1;
    }
    array = performNTT(array, k, false);
    for (int i = 0; i < size; i++) {
        array[i] = powerMod(array[i], n);
    }
    array = performNTT(array, k, true);
    long long totalSum = 0;
    for (int i = 0; i < size; i++) {
        totalSum = (totalSum + array[i] * array[i]) % MOD;
    }
    long long invSize = inverseMod(size);
    long long result = (((totalSum * invSize) % MOD) * invSize) % MOD;
    cout << result << "\n";
    return 0;
}

